parameters.jsCode:
// Script simplificado para n8n - Extração de data_proxima_execucao, data_desativacao e descricao

// Obtém o texto de entrada do item
const texto = $input.first().json.output || $input.first().json.output || '';

// Função para extrair valores de forma segura
function extrairCampo(texto, nomeCampo) {
  try {
    // Normaliza o texto removendo múltiplos espaços mas mantendo quebras de linha
    const textoLimpo = texto.replace(/\r/g, '');

    // Cria regex para capturar o valor do campo
    // Procura pelo nome do campo seguido de : e captura até o próximo campo ou fim
    const regex = new RegExp(
      `${nomeCampo}:\\s*([^\\n]*?)(?=\\s*(?:data_proxima_execucao|data_desativacao|descricao):|$)`,
      'si'
    );

    const match = textoLimpo.match(regex);

    if (match && match[1] !== undefined) {
      // Remove espaços extras e retorna o valor
      return match[1].trim();
    }

    return '';
  } catch (error) {
    console.error(`Erro ao extrair ${nomeCampo}:`, error);
    return '';
  }
}

try {
  // Extrai os três campos
  const data_proxima_execucao = extrairCampo(texto, 'data_proxima_execucao');
  const data_desativacao = extrairCampo(texto, 'data_desativacao');
  const descricao = extrairCampo(texto, 'descricao');

  // Monta o objeto de saída
  const resultado = {
    data_proxima_execucao: data_proxima_execucao || null,
    data_desativacao: data_desativacao || null,
    descricao: descricao || null
  };

  // Adiciona informações extras úteis
  if (data_proxima_execucao) {
    try {
      const dataObj = new Date(data_proxima_execucao);
      resultado.data_proxima_valida = !isNaN(dataObj.getTime());
      if (resultado.data_proxima_valida) {
        resultado.data_proxima_formatada = dataObj.toISOString();
      }
    } catch (e) {
      resultado.data_proxima_valida = false;
    }
  }

  if (data_desativacao) {
    try {
      const dataObj = new Date(data_desativacao);
      resultado.data_desativacao_valida = !isNaN(dataObj.getTime());
      if (resultado.data_desativacao_valida) {
        resultado.data_desativacao_formatada = dataObj.toISOString();
      }
    } catch (e) {
      resultado.data_desativacao_valida = false;
    }
  }

  // Retorna o resultado
  return resultado;

} catch (error) {
  // Em caso de erro, retorna objeto com erro
  return {
    erro: true,
    mensagem: error.message,
    data_proxima_execucao: null,
    data_desativacao: null,
    descricao: null
  };
}

parameters.messageText:
=Lembrete criado com sucesso! 📝 

{{ $json.dsc_lembrete ?? 'Sua solicitação: '+ $json.prompt_lembrete}}

Vou enviar uma mensagem para te lembrar {{ 
  (() => {
    const data = DateTime.fromISO($('proxima_exec_menor_2_dias').item.json.dt_proxima_exec, { zone: 'utc' });
    const hoje = DateTime.now().setZone('utc').startOf('day');
    const amanha = hoje.plus({ days: 1 });
    const dataInicioDia = data.startOf('day');

    return dataInicioDia.equals(hoje) ? `hoje às ${data.toFormat('HH:mm')}` :
           dataInicioDia.equals(amanha) ? `amanhã às ${data.toFormat('HH:mm')}` :
           `no dia ${data.toFormat('dd/MM/yyyy')} às ${data.toFormat('HH:mm')}`;
  })()
}}

